    __shared__ float shB[32][33];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Load shA tile - multiple rows per thread
    for (int ll = 0; ll < RM; ++ll) {
        int row_sh = ty * RM + ll;
        if (row_sh < BM && tx < K) {
            int gi = by * BM + row_sh;
            if (gi < M) {
                shA[row_sh][tx] = A[gi * K + tx];
            }
