gemm_cpp = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
__global__ void gemm_kernel(const float *A, const float *B, float *C, int M, int K, int N) {
    constexpr int BM_THREADS = 32;
    constexpr int BN_THREADS = 32;
    constexpr int RM = 2;
    constexpr int BM = BM_THREADS * RM;  // 64
    constexpr int BN = BN_THREADS * 1;  // 32
    __shared__ float shA[64][33];
    __shared__ float shB[32][33];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Load shA tile - multiple rows per thread
    for (int ll = 0; ll < RM; ++ll) {
        int row_sh = ty * RM + ll;
        if (row_sh < BM && tx < K) {
            int gi = by * BM + row_sh;
            if (gi < M) {
                shA[row_sh][tx] = A[gi * K + tx];
            }
        }
    }
    // Load shB tile
    for (int ll = 0; ll < 1; ++ll) {  // since RM_threads wait no, for shB use RM for K? Wait adjust
        int kk = ty * 1 + ll;
        if (kk < K && bx * BN + tx < N) {
            shB[kk][tx] = B[kk * N + bx * BN + tx];
        }
    }
    __syncthreads();

    // Compute multiple
    int base_i = by * BM + ty * RM;
    int j = bx * BN + tx;
    if (base_i < M && j < N) {
        for (int rm = 0; rm < RM; ++rm) {
            int ii = base_i + rm;
            if (ii < M) {
                float sum = 0.0f;
                #pragma unroll
                for (int k = 0; k < K; ++k) {
                    sum += shA[ty * RM + rm][k] * shB[k][tx];
                }
                C[ii * N + j] = sum;
            }
        }
    }
}
torch::Tensor gemm_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);
    auto C = torch::zeros({M, N}, A.options());
    constexpr int BM_THREADS = 32;
    constexpr int BN_THREADS = 32;
    constexpr int RM = 2;
    constexpr int BM = BM_THREADS * RM;
    constexpr int BN = BN_THREADS;
    dim3 block(BN_THREADS, BM_THREADS);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);
    gemm_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(),
                                 C.data_ptr<float>(), (int)M, (int)K, (int)N);
    return C;
}
